          const root3 = native ? this.nativeWorkContext ? await this.nativeWorkContext(native) : native : this.currentWorkRoot?.() ?? this.contextUuid;
          if (epoch !== this.epoch || ticket !== this.linkEpoch || this.disposed || native && root3 === null) return;
          this.contextUuid = root3;
          await this.openPreviewLink(href, root3);
        })().catch(this.fail);
      }

